package ama.transcript;
import ama.contract.MinutesContracts.*;import java.util.*;import org.junit.jupiter.api.Test;
import static ama.contract.MinutesContracts.*;import static org.junit.jupiter.api.Assertions.*;
class MinutesInfoSuggestionValuesTest {
 FullRow row(Table table,Object...values){return new FullRow(table,Arrays.stream(values).map(x->x==null?(Cell)new NullCell():x instanceof Long n?cell(n):cell((String)x)).toList());}
 List<FullRow> graph(){return List.of(row(Table.MINUTES_REVISION,"6c148ca6-edb7-56e2-9ade-3662fdf1017f","eae2de2f-2b36-5581-ab67-8b5b3c669242",1L,null,"建议名称","AI","完整正文不是摘要","2a1fc7ed-4411-52af-a4bb-80bc03f5780d","owner","2026-11-01T00:00:00.000000Z"),row(Table.MINUTES_REVISION,"d0db777f-e58b-5ff4-84ba-af70aae4a2e4","eae2de2f-2b36-5581-ab67-8b5b3c669242",2L,null,"人工名称","HUMAN","人工正文","0856d85e-e2b6-5bc7-a782-8ecd9d130396","owner","2026-11-01T00:00:01.000000Z"),row(Table.MINUTES_ELEMENT,"08030a32-e53a-5fa4-b824-fd6862dbae26","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","OVERVIEW",2L,"概览二","UNSUPPORTED"),row(Table.MINUTES_ELEMENT,"448d8aab-5165-55cf-97c1-375f3d537637","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","OVERVIEW",1L,"概览一","UNSUPPORTED"),row(Table.MINUTES_ELEMENT,"464b3f47-d5d1-5c41-8186-8095d08ffe01","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","DISCUSSION",1L,"讨论不要混入摘要","UNSUPPORTED"),row(Table.MINUTES_ELEMENT,"63afe3b8-50ae-55dd-be3a-eb709954e8ff","67bcb9b1-ecc7-5670-accd-8759b3e673cb","OVERVIEW",1L,"历史概览","UNSUPPORTED"));}
 @Test void nameUsesOnlyExactAiCandidateAndSummaryUsesOnlyItsOrderedOverview(){var values=MinutesInfoSuggestionValues.from(graph(),"eae2de2f-2b36-5581-ab67-8b5b3c669242","6c148ca6-edb7-56e2-9ade-3662fdf1017f","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","2a1fc7ed-4411-52af-a4bb-80bc03f5780d");assertEquals(Map.of("NAME","建议名称","SUMMARY","概览一\n概览二"),values);}
 @Test void humanOrForeignInputCannotBecomeAnAiProposal(){assertThrows(Failure.class,()->MinutesInfoSuggestionValues.from(graph(),"eae2de2f-2b36-5581-ab67-8b5b3c669242","d0db777f-e58b-5ff4-84ba-af70aae4a2e4","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","0856d85e-e2b6-5bc7-a782-8ecd9d130396"));assertThrows(Failure.class,()->MinutesInfoSuggestionValues.from(graph(),"eae2de2f-2b36-5581-ab67-8b5b3c669242","6c148ca6-edb7-56e2-9ade-3662fdf1017f","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","12ba36b9-4e30-5cbb-ace5-f609a325ff99"));assertThrows(Failure.class,()->MinutesInfoSuggestionValues.from(graph(),"dc55ffef-7949-571e-8fd7-9985fa42c31d","6c148ca6-edb7-56e2-9ade-3662fdf1017f","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","2a1fc7ed-4411-52af-a4bb-80bc03f5780d"));}
 @Test void emptyOverviewNeverFallsBackToMinutesBody(){var rows=graph().stream().filter(r->r.table()!=Table.MINUTES_ELEMENT).toList();assertEquals(Map.of("NAME","建议名称"),MinutesInfoSuggestionValues.from(rows,"eae2de2f-2b36-5581-ab67-8b5b3c669242","6c148ca6-edb7-56e2-9ade-3662fdf1017f","1321c29c-222a-5a1d-adbb-e96a9d4c5ed3","2a1fc7ed-4411-52af-a4bb-80bc03f5780d"));}
}
